async function route(req, env) {
  if (new URL(req.url).pathname === '/version') return new Response("BotDo'kon YANGI versiya: 12-noyabr (AI shar, yangi menyu)", { headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
  const url = new URL(req.url), origin = url.origin, M = req.method;
  const p = url.pathname.split('/').filter(Boolean);
  const body = async () => { try { return await req.json(); } catch { return {}; } };

  if (!env.DB) return html('<h2 style="font-family:sans-serif;padding:30px">KV ulanmagan: Settings → Bindings → KV namespace, nomi <b>DB</b></h2>');
  if (M === 'GET' && !p.length) return Response.redirect(origin + '/admin', 302);
  if (M === 'GET' && p[0] === 'admin' && p.length === 1) return html(ADMIN_HTML);
  if (M === 'GET' && p[0] === 'app' && p.length === 2) return html(APP_HTML);
  if (M === 'GET' && (p[0] === 'img' || p[0] === 'uploads') && p[1]) {
    const { value, metadata } = await kv(env).getWithMetadata('img:' + p[1], 'arrayBuffer');
    if (!value) return new Response('Topilmadi', { status: 404 });
    return new Response(value, { headers: { 'Content-Type': (metadata && metadata.type) || 'image/jpeg', 'Cache-Control': 'public, max-age=31536000, immutable' } });
  }

  // Telegram webhook
  if (M === 'POST' && p[0] === 'tg' && p[1]) {
    const bot = await getBot(env, p[1]);
    if (!bot || req.headers.get('X-Telegram-Bot-Api-Secret-Token') !== bot.secret) return new Response('no', { status: 403 });
    const upd = await body();
    const job = handleUpdate(env, origin, bot, upd).catch((e) => console.log('update error', e.message));
    if (env.__ctx && env.__ctx.waitUntil) env.__ctx.waitUntil(job); else await job;
    return new Response('ok');
  }

  // Mini App API
  if (p[0] === 'api' && p[1] === 'shop') {
    const bot = await getBot(env, p[2]); if (!bot) return err("Topilmadi", 404);
    if (M === 'GET' && p.length === 3) return json({ ...publicShop(bot), ai: aiReady(env, bot), aiName: aiName(bot) });
    if (M === 'POST' && p[3] === 'ai') {
      if (!aiReady(env, bot)) return err("Yordamchi o'chirilgan", 400);
      const b = await body();
      const ip = req.headers.get('CF-Connecting-IP') || 'x', day = new Date().toISOString().slice(0, 10), ck = `ailim:${bot.id}:${ip}:${day}`;
      const used = parseInt((await kv(env).get(ck)) || '0', 10);
      if (used >= 80) return err("Bugungi savollar soni tugadi. Ertaga yozing yoki telefon qiling.", 429);
      await kv(env).put(ck, String(used + 1), { expirationTtl: 90000 });
      const msgs = (Array.isArray(b.messages) ? b.messages : []).slice(-10)
        .filter((m) => m && (m.role === 'user' || m.role === 'assistant') && m.content).map((m) => ({ role: m.role, content: String(m.content).slice(0, 800) }));
      if (!msgs.length || msgs[msgs.length - 1].role !== 'user') return err('Savol yozing');
      const reply = await aiChat(env, bot, msgs);
      return reply ? json({ reply }) : err("Hozir javob bera olmayapman, birozdan keyin urinib ko'ring", 502);
    }
    if (M === 'POST' && p[3] === 'orders') {
      const user = await verifyInitData((await body()).initData, bot.token);
      if (!user || !user.id) return json([]);
      return json((await getOrders(env, bot.id)).filter((o) => String(o.customer.chatId) === String(user.id)).slice(-30).reverse()
        .map((o) => ({ id: o.id, number: o.number, items: o.items, total: o.total, status: o.status, statusText: STATUS[o.status], createdAt: o.createdAt })));
    }
    if (M === 'POST' && p[3] === 'order') {
      const b = await body(), user = await verifyInitData(b.initData, bot.token);
      if (!user) return err("Iltimos, ilovani Telegram bot orqali oching", 403);
      const items = [];
      for (const it of (b.items || []).slice(0, 100)) {
        const pr = bot.products.find((x) => x.id === it.id && x.active);
        const vr = pr && pr.variants && pr.variants.length && it.v != null ? pr.variants[parseInt(it.v)] : null;
        if (pr && pr.variants && pr.variants.length && !vr) continue;
        if (pr) items.push({ id: pr.id, name: vr ? `${pr.name} (${vr.name})` : pr.name, price: vr ? vr.price : pr.price, qty: Math.min(999, Math.max(1, parseInt(it.qty) || 1)), unit: vr ? '' : pr.unit });
      }
      if (!items.length) return err("Savat bo'sh");
      const c = b.customer || {};
      if (!str(c.name) || !str(c.phone) || !str(c.address)) return err('Ism, telefon va manzilni kiriting');
      const s = bot.settings, subtotal = items.reduce((a, i) => a + i.price * i.qty, 0);
      if (s.minOrder && subtotal < s.minOrder) return err(`Minimal buyurtma ${fmt(s.minOrder)}`);
      const used = s.promoCode && String(b.promoCode || '').toUpperCase() === s.promoCode && subtotal >= (s.promoMin || 0);
      const discount = used ? Math.min(num(s.promoDiscount), subtotal) : 0;
      const list = await getOrders(env, bot.id);
      const o = { id: uid(), botId: bot.id, number: (list.length ? list[list.length - 1].number : 1000) + 1, items, subtotal,
        deliveryFee: num(s.deliveryFee), discount, promoCode: used ? s.promoCode : '', total: subtotal + num(s.deliveryFee) - discount,
        payment: b.payment === 'card' ? 'card' : 'cash', status: 'new', createdAt: now(),
        customer: { chatId: user.id, username: user.username || '', name: str(c.name, 80), phone: str(c.phone, 30), address: str(c.address, 300), comment: str(c.comment, 300),
          location: c.location && isFinite(c.location.lat) ? { lat: +c.location.lat, lng: +c.location.lng } : null } };
      if (bot.ownerChatId) {
        const r = await tg(bot.token, 'sendMessage', { chat_id: bot.ownerChatId, text: orderText(o), parse_mode: 'HTML', disable_web_page_preview: true, reply_markup: { inline_keyboard: ownerButtons(o) } });
        if (o.customer.location) await tg(bot.token, 'sendLocation', { chat_id: bot.ownerChatId, latitude: o.customer.location.lat, longitude: o.customer.location.lng, reply_to_message_id: r.ok && r.result ? r.result.message_id : undefined });
        if (r.ok) o.ownerMsgId = r.result.message_id;
      }
      list.push(o); await putOrders(env, bot.id, list);
      return json({ ok: true, number: o.number });
    }
  }

  // Admin API
  if (p[0] === 'api' && p[1] === 'admin') {
    const stored = await kv(env).get('admin_hash');
    if (p[2] === 'status') return json({ needSetup: !env.ADMIN_PASSWORD && !stored });
    if (M === 'POST' && p[2] === 'setup') {
      if (env.ADMIN_PASSWORD || stored) return err("Parol allaqachon o'rnatilgan", 403);
      const pw = str((await body()).password, 100);
      if (pw.length < 6) return err("Parol kamida 6 belgidan iborat bo'lsin");
      await kv(env).put('admin_hash', await sha(pw));
      return json({ ok: true });
    }
    const key = req.headers.get('x-admin-key') || '';
    if (!key) return err("Parol noto'g'ri", 401);
    const keyHash = await sha(key);
    const isSuper = env.ADMIN_PASSWORD ? key === env.ADMIN_PASSWORD : (stored && keyHash === stored);
    let ownBot = null;
    if (!isSuper) {
      ownBot = (await allBots(env)).find((b) => b.ownerPassHash && b.ownerPassHash === keyHash);
      if (!ownBot) return err("Parol noto'g'ri", 401);
    }
    const role = isSuper ? 'super' : 'owner';
    if (p[2] === 'me') return json({ ok: true, baseUrl: origin, role, botId: ownBot ? ownBot.id : null });
    // Bot egasi faqat o'z botiga kira oladi
    if (role === 'owner') {
      const allowed = p[2] === 'upload' || (p[2] === 'orders' && M === 'PUT') ||
        (p[2] === 'bots' && p[3] === ownBot.id && !(M === 'DELETE' && p.length === 4) && p[4] !== 'resetup');
      if (!allowed) return err("Ruxsat yo'q", 403);
    }
    if (M === 'POST' && p[2] === 'upload') {
      const ct = req.headers.get('Content-Type') || '';
      let buf, type;
      if (ct.startsWith('image/')) { buf = await req.arrayBuffer(); type = ct.split(';')[0]; }
      else {
        const m = /^data:(image\/(?:png|jpe?g|webp));base64,(.+)$/.exec((await body()).data || '');
        if (!m) return err("Rasm formati noto'g'ri");
        buf = Uint8Array.from(atob(m[2]), (ch) => ch.charCodeAt(0)).buffer; type = m[1];
      }
      if (!/^image\/(png|jpe?g|webp)$/.test(type)) return err('Faqat JPG, PNG yoki WEBP rasm');
      if (buf.byteLength > 5 * 1024 * 1024) return err('Rasm juda katta (5 MB dan oshmasin)');
      const id = uid() + (type === 'image/png' ? '.png' : type === 'image/webp' ? '.webp' : '.jpg');
      await kv(env).put('img:' + id, buf, { metadata: { type } });
      return json({ url: '/img/' + id });
    }
    if (M === 'PUT' && p[2] === 'orders' && p[3]) {
      const st = (await body()).status;
      for (const bot of await allBots(env)) {
        if (ownBot && bot.id !== ownBot.id) continue;
        const list = await getOrders(env, bot.id), o = list.find((x) => x.id === p[3]);
        if (o) { await setStatus(env, bot, o, st, list); return json({ ok: true }); }
      }
      return err('Topilmadi', 404);
    }
    if (p[2] !== 'bots') return err('Topilmadi', 404);
    const summary = async (b) => ({ id: b.id, type: b.type, username: b.username, name: b.settings.shopName || b.name, active: true, error: b.error || '',
      ownerChatId: b.ownerChatId || '', appUrl: appUrl(origin, b), products: b.products.length, orders: (await getOrders(env, b.id)).length });
    if (M === 'GET' && p.length === 3) return json(await Promise.all((await allBots(env)).map(summary)));
    if (M === 'POST' && p.length === 3) {
      const b = await body(), token = str(b.token, 100);
      if (!/^\d+:[\w-]{30,}$/.test(token)) return err("Token formati noto'g'ri");
      const me = await tg(token, 'getMe');
      if (!me.ok) return err('Telegram tokenni qabul qilmadi: ' + (me.description || ''));
      const type = TYPES[b.type] ? b.type : 'restaurant', ids = await botIds(env);
      let bot = (await allBots(env)).find((x) => x.tgId === me.result.id);
      if (bot) Object.assign(bot, { token, type, error: '' });
      else {
        bot = { id: uid(), type, tgId: me.result.id, token, secret: uid() + uid(), username: me.result.username, name: me.result.first_name,
          ownerChatId: '', createdAt: now(), settings: newSettings(), categories: [], products: [], banners: [] };
        ids.push(bot.id); await kv(env).put('bots', JSON.stringify(ids));
      }
      const r = await setupBot(origin, bot);
      bot.error = r.ok ? '' : 'Bot sozlanmadi: ' + (r.description || '');
      await putBot(env, bot);
      return json(await summary(bot));
    }
    const bot = await getBot(env, p[3]); if (!bot) return err('Bot topilmadi', 404);
    if (M === 'GET' && p.length === 4) { const { token, secret, ownerPassHash, ...rest } = bot; return json({ ...rest, hasOwnerPass: !!ownerPassHash, role, appUrl: appUrl(origin, bot) }); }
    if (M === 'DELETE' && p.length === 4) {
      await tg(bot.token, 'deleteWebhook', {}); await tg(bot.token, 'setChatMenuButton', { menu_button: { type: 'default' } });
      await kv(env).put('bots', JSON.stringify((await botIds(env)).filter((x) => x !== bot.id)));
      await kv(env).delete('bot:' + bot.id); await kv(env).delete('orders:' + bot.id);
      return json({ ok: true });
    }
    if (M === 'POST' && p[4] === 'resetup') { const r = await setupBot(origin, bot); bot.error = r.ok ? '' : (r.description || 'Xato'); await putBot(env, bot); return json({ ok: r.ok, error: bot.error }); }
    if (M === 'POST' && p[4] === 'ai-scan') {
      if (!env.AI) return err("Sun'iy intellekt ulanmagan: Settings → Bindings → Add binding → Workers AI, nomi AI", 400);
      const ct = (req.headers.get('Content-Type') || '').split(';')[0];
      if (!/^image\/(png|jpe?g|webp)$/.test(ct)) return err('Rasm yuboring (JPG, PNG)');
      const buf = await req.arrayBuffer();
      if (buf.byteLength > 4 * 1024 * 1024) return err('Rasm juda katta');
      let items;
      try { items = await aiScan(env, buf, ct, bot.type); } catch (e) { return err("Sun'iy intellekt xatosi: " + String(e && e.message || e).slice(0, 160), 502); }
      if (!items.length) return err("Rasmdan mahsulot topilmadi. Aniqroq, yaqinroq rasm oling.");
      const url = new URL(req.url);
      if (url.searchParams.get('img') !== '0') {
        for (let i = 0; i < items.length; i += 6) await Promise.all(items.slice(i, i + 6).map(async (x) => { x.image = await findImage(env, x.name); }));
      }
      return json({ items });
    }
    if (M === 'GET' && p[4] === 'find-image') {
      const u = await findImage(env, new URL(req.url).searchParams.get('q'));
      return u ? json({ url: u }) : err('Rasm topilmadi', 404);
    }
    if (M === 'POST' && p[4] === 'test') {
      if (!bot.ownerChatId) return err('Avval Chat ID ni kiriting');
      const r = await tg(bot.token, 'sendMessage', { chat_id: bot.ownerChatId, text: '✅ Sinov xabari: buyurtmalar shu chatga keladi.' });
      return r.ok ? json({ ok: true }) : err('Yuborilmadi: ' + r.description + '. Egasi avval botga /start bosishi kerak.');
    }
    if (M === 'PUT' && p[4] === 'settings') {
      const b = await body(), s = bot.settings;
      for (const k of ['promoText', 'promoDetail', 'phone', 'workHours', 'deliveryTime', 'address']) s[k] = str(b[k], 1000);
      for (const k of ['saleTitle', 'topTitle']) s[k] = str(b[k], 50);
      for (const k of ['saleCover', 'topCover', 'logo']) s[k] = str(b[k], 300);
      s.lat = Number.isFinite(+b.lat) && b.lat !== '' && b.lat !== null ? +(+b.lat).toFixed(6) : null; s.lng = Number.isFinite(+b.lng) && b.lng !== '' && b.lng !== null ? +(+b.lng).toFixed(6) : null;
      if ('aiOn' in b) s.aiOn = !!b.aiOn; s.aiName = str(b.aiName, 60); s.aiInfo = str(b.aiInfo, 3000);
      s.shopName = str(b.shopName, 60); s.color = str(b.color, 20) || '#7000FF'; s.welcomeText = str(b.welcomeText, 1000) || s.welcomeText;
      for (const k of ['deliveryFee', 'minOrder', 'promoDiscount', 'promoMin']) s[k] = num(b[k]);
      s.promoCode = str(b.promoCode, 30).toUpperCase(); bot.ownerChatId = str(b.ownerChatId, 30);
      let changed = false;
      if (role === 'super') {
        changed = TYPES[b.type] && b.type !== bot.type; if (changed) bot.type = b.type;
        const op = str(b.ownerPassword, 100);
        if (b.removeOwnerPass) delete bot.ownerPassHash;
        else if (op) {
          if (op.length < 6) return err("Egasi paroli kamida 6 belgi bo'lsin");
          const h = await sha(op);
          if (h === stored || op === env.ADMIN_PASSWORD || (await allBots(env)).some((x) => x.id !== bot.id && x.ownerPassHash === h)) return err('Bu parol band, boshqasini tanlang');
          bot.ownerPassHash = h;
        }
      }
      await putBot(env, bot); if (changed) await setupBot(origin, bot);
      return json({ ok: true });
    }
    if (M === 'GET' && p[4] === 'orders') return json((await getOrders(env, bot.id)).slice(-200).reverse().map((o) => ({ ...o, statusText: STATUS[o.status] })));
    const f = COLL[p[4]];
    if (M === 'POST' && p[4] === 'import') {
      const b = await body(), cats = (Array.isArray(b.categories) ? b.categories : []).slice(0, 60);
      if (!cats.length) return err("Faylda kategoriya yo'q");
      const { nc, np } = importInto(bot, cats, b.replace);
      if (bot.products.length > 2000) return err("Mahsulotlar juda ko'p (2000 dan ortiq)");
      await putBot(env, bot); return json({ ok: true, categories: nc, products: np });
    }
    if (f) {
      const list = bot[p[4]];
      if (M === 'POST' && p[5] === 'bulk') {
        const arr = ((await body()).items || []).slice(0, 80);
        const added = arr.map((x) => ({ id: uid(), ...f(x) })).filter((x) => x.name || x.image);
        list.push(...added); await putBot(env, bot); return json({ ok: true, added: added.length });
      }
      if (M === 'POST' && p.length === 5) { const it = { id: uid(), ...f(await body()) }; list.push(it); await putBot(env, bot); return json(it); }
      const i = list.findIndex((x) => x.id === p[5]); if (i < 0) return err('Topilmadi', 404);
      if (M === 'PUT') { list[i] = { id: list[i].id, ...f(await body()) }; await putBot(env, bot); return json(list[i]); }
      if (M === 'DELETE') {
        list.splice(i, 1);
        if (p[4] === 'categories') bot.products.forEach((x) => { if (x.categoryId === p[5]) x.categoryId = ''; });
        await putBot(env, bot); return json({ ok: true });
      }
    }
  }
  return err('Topilmadi', 404);
}

export default {
  async fetch(req, env, ctx) {
    try { if (ctx) Object.defineProperty(env, '__ctx', { value: ctx, configurable: true, writable: true }); } catch {}
    if (ctx && ctx.waitUntil && !seedDone) ctx.waitUntil(autoSeed(env).catch(() => {}));
    try { return await route(req, env); }
    catch (e) { return err('Server xatosi: ' + e.message, 500); }
  },
};
